insert into public.products (id, slug, category_id, name_ko, name_en, description_ko, description_en, price, images, is_published, created_at) values
  ('20000000-0000-4000-8000-000000000001', 'stainless-tumbler', '10000000-0000-4000-8000-000000000001', '스테인리스 텀블러', 'Stainless Tumbler', '출퇴근길 커피를 6시간 따뜻하게. 이중 진공 구조라 겉면에 물방울이 맺히지 않습니다.', 'Keeps your commute coffee warm for 6 hours with double-wall vacuum insulation.', 19800, array['/products/stainless-tumbler.svg']::text[], true, '2026-11-01T00:00:00.000Z'),
  ('20000000-0000-4000-8000-000000000002', 'silicone-spatula-set', '10000000-0000-4000-8000-000000000001', '실리콘 주걱 세트', 'Silicone Spatula Set', '코팅 팬을 긁지 않는 실리콘 주걱 3종. 230℃까지 견딥니다.', 'Three pan-safe silicone spatulas, heat resistant up to 230°C.', 12900, array['/products/silicone-spatula-set.svg']::text[], true, '2026-11-01T00:01:00.000Z'),
  ('20000000-0000-4000-8000-000000000003', 'glass-container-set', '10000000-0000-4000-8000-000000000001', '내열유리 밀폐용기 3종', 'Glass Container Set (3)', '전자레인지·오븐 사용 가능한 내열유리 용기. 도시락 준비에 알맞습니다.', 'Oven and microwave safe glass containers, perfect for meal prep.', 24900, array['/products/glass-container-set.svg']::text[], true, '2026-11-01T00:02:00.000Z'),
  ('20000000-0000-4000-8000-000000000004', 'bamboo-cutting-board', '10000000-0000-4000-8000-000000000001', '대나무 도마', 'Bamboo Cutting Board', '가볍고 칼자국이 덜 남는 대나무 도마.', 'Lightweight bamboo board that resists knife marks.', 15900, array['/products/bamboo-cutting-board.svg']::text[], true, '2026-11-01T00:03:00.000Z'),
  ('20000000-0000-4000-8000-000000000005', 'drip-kettle', '10000000-0000-4000-8000-000000000001', '드립 커피 주전자', 'Pour-over Kettle', '가는 주둥이로 물줄기를 조절하기 쉬운 600ml 드립 주전자.', 'A 600ml gooseneck kettle for precise pour-over.', 32000, array['/products/drip-kettle.svg']::text[], true, '2026-11-01T00:04:00.000Z'),
  ('20000000-0000-4000-8000-000000000006', 'dish-rack', '10000000-0000-4000-8000-000000000001', '2단 식기건조대', 'Two-tier Dish Rack', '좁은 싱크대에도 들어가는 슬림 2단 건조대.', 'Slim two-tier rack that fits narrow counters.', 38000, array['/products/dish-rack.svg']::text[], true, '2026-11-01T00:05:00.000Z'),
  ('20000000-0000-4000-8000-000000000007', 'cotton-towel', '10000000-0000-4000-8000-000000000002', '호텔식 면 타월 (2장)', 'Hotel Cotton Towel (2 pcs)', '40수 코마사로 짠 부드러운 타월 2장 세트.', 'Soft 40-count combed cotton towels, set of two.', 16900, array['/products/cotton-towel.svg']::text[], true, '2026-11-01T00:06:00.000Z'),
  ('20000000-0000-4000-8000-000000000008', 'foam-dispenser', '10000000-0000-4000-8000-000000000002', '자동 거품 디스펜서', 'Automatic Foam Dispenser', '손을 대면 거품이 나오는 충전식 디스펜서.', 'Touch-free rechargeable foam soap dispenser.', 27900, array['/products/foam-dispenser.svg']::text[], true, '2026-11-01T00:07:00.000Z'),
  ('20000000-0000-4000-8000-000000000009', 'diatomite-bath-mat', '10000000-0000-4000-8000-000000000002', '규조토 발매트', 'Diatomite Bath Mat', '물기를 빠르게 흡수하고 금방 마르는 규조토 매트.', 'Quick-drying diatomaceous earth bath mat.', 21000, array['/products/diatomite-bath-mat.svg']::text[], true, '2026-11-01T00:08:00.000Z'),
  ('20000000-0000-4000-8000-000000000010', 'toothbrush-holder', '10000000-0000-4000-8000-000000000002', '벽걸이 칫솔걸이', 'Wall Toothbrush Holder', '못 없이 붙이는 칫솔걸이. 물이 고이지 않는 구조.', 'Adhesive wall holder that drains water.', 9900, array['/products/toothbrush-holder.svg']::text[], true, '2026-11-01T00:09:00.000Z'),
  ('20000000-0000-4000-8000-000000000011', 'shower-filter', '10000000-0000-4000-8000-000000000002', '샤워 필터 헤드', 'Filtered Shower Head', '녹물과 잔류 염소를 걸러주는 필터 샤워기.', 'Shower head with a replaceable filter.', 18500, array['/products/shower-filter.svg']::text[], true, '2026-11-01T00:10:00.000Z'),
  ('20000000-0000-4000-8000-000000000012', 'laundry-basket', '10000000-0000-4000-8000-000000000002', '접이식 빨래 바구니', 'Foldable Laundry Basket', '안 쓸 때는 납작하게 접어 두는 빨래 바구니.', 'Folds flat when not in use.', 14900, array['/products/laundry-basket.svg']::text[], true, '2026-11-01T00:11:00.000Z'),
  ('20000000-0000-4000-8000-000000000013', 'stacking-box', '10000000-0000-4000-8000-000000000003', '스태킹 수납함', 'Stacking Storage Box', '쌓아도 안정적인 투명 수납함. 크기별로 섞어 쓰기 좋습니다.', 'Clear stackable boxes in three sizes.', 11900, array['/products/stacking-box.svg']::text[], true, '2026-11-01T00:12:00.000Z'),
  ('20000000-0000-4000-8000-000000000014', 'drawer-organizer', '10000000-0000-4000-8000-000000000003', '서랍 정리 트레이 6종', 'Drawer Organizer (6 pcs)', '서랍 크기에 맞춰 조합하는 정리 트레이.', 'Mix-and-match trays for any drawer.', 13500, array['/products/drawer-organizer.svg']::text[], true, '2026-11-01T00:13:00.000Z'),
  ('20000000-0000-4000-8000-000000000015', 'nonslip-hanger', '10000000-0000-4000-8000-000000000003', '논슬립 옷걸이 20개', 'Non-slip Hangers (20)', '옷이 미끄러지지 않는 얇은 벨벳 옷걸이.', 'Slim velvet hangers that keep clothes in place.', 15000, array['/products/nonslip-hanger.svg']::text[], true, '2026-11-01T00:14:00.000Z'),
  ('20000000-0000-4000-8000-000000000016', 'cable-organizer', '10000000-0000-4000-8000-000000000003', '케이블 정리함', 'Cable Organizer Box', '멀티탭과 전선을 숨기는 정리함.', 'Hides power strips and tangled cables.', 17900, array['/products/cable-organizer.svg']::text[], true, '2026-11-01T00:15:00.000Z'),
  ('20000000-0000-4000-8000-000000000017', 'slim-shoe-rack', '10000000-0000-4000-8000-000000000003', '슬림 신발장 정리대', 'Slim Shoe Rack', '신발장 공간을 두 배로 쓰는 2단 정리대.', 'Doubles your shoe cabinet space.', 29900, array['/products/slim-shoe-rack.svg']::text[], true, '2026-11-01T00:16:00.000Z'),
  ('20000000-0000-4000-8000-000000000018', 'vacuum-bags', '10000000-0000-4000-8000-000000000003', '압축팩 5매', 'Vacuum Storage Bags (5)', '계절 이불과 옷 부피를 줄여주는 압축팩.', 'Shrinks bulky bedding and clothes.', 12000, array['/products/vacuum-bags.svg']::text[], true, '2026-11-01T00:17:00.000Z'),
  ('20000000-0000-4000-8000-000000000019', 'microfiber-cloth', '10000000-0000-4000-8000-000000000004', '극세사 행주 10매', 'Microfiber Cloths (10)', '흡수력 좋고 빨리 마르는 극세사 행주.', 'Absorbent, quick-drying microfiber cloths.', 8900, array['/products/microfiber-cloth.svg']::text[], true, '2026-11-01T00:18:00.000Z'),
  ('20000000-0000-4000-8000-000000000020', 'cordless-mop', '10000000-0000-4000-8000-000000000004', '무선 물걸레 청소기', 'Cordless Spin Mop', '회전 패드로 바닥을 닦는 무선 청소기. (품절 표시 예시 상품)', 'Cordless spinning mop. (Sold-out example item)', 89000, array['/products/cordless-mop.svg']::text[], true, '2026-11-01T00:19:00.000Z'),
  ('20000000-0000-4000-8000-000000000021', 'lint-roller', '10000000-0000-4000-8000-000000000004', '리필형 돌돌이', 'Refillable Lint Roller', '먼지와 머리카락을 떼어내는 리필형 클리너.', 'Picks up lint and hair, refillable.', 7500, array['/products/lint-roller.svg']::text[], true, '2026-11-01T00:20:00.000Z'),
  ('20000000-0000-4000-8000-000000000022', 'eco-cleaner', '10000000-0000-4000-8000-000000000004', '친환경 다목적 세정제', 'Eco All-purpose Cleaner', '식물 유래 성분의 다목적 세정제.', 'Plant-based all-purpose cleaner.', 9800, array['/products/eco-cleaner.svg']::text[], true, '2026-11-01T00:21:00.000Z'),
  ('20000000-0000-4000-8000-000000000023', 'static-duster', '10000000-0000-4000-8000-000000000004', '정전기 먼지떨이', 'Static Duster', '틈새 먼지까지 붙잡는 정전기 먼지떨이.', 'Grabs dust from tight spots.', 6900, array['/products/static-duster.svg']::text[], true, '2026-11-01T00:22:00.000Z'),
  ('20000000-0000-4000-8000-000000000024', 'pedal-trash-can', '10000000-0000-4000-8000-000000000004', '페달 휴지통 12L', 'Pedal Trash Can 12L', '뚜껑이 조용히 닫히는 페달식 휴지통.', 'Soft-close pedal bin.', 24000, array['/products/pedal-trash-can.svg']::text[], true, '2026-11-01T00:23:00.000Z')
